/// <summary>
/// Service class for transfer order backorder cancellation.
/// </summary>
class METTransferOrderBackOrderCancelService extends METSysOperationService
{
    METTransferOrderBackOrderCancelContract contract;
    guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Returns name of the task service class.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METTransferOrderBackOrderCancelTaskService);
}

/// <summary>
/// Returns name of the task service class method.
/// </summary>
/// <returns>Task service class method name</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METTransferOrderBackOrderCancelTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:TransferOrderBackOrderCancel";
}

/// <summary>
/// Initialise global variables.
/// </summary>
public void initialise()
{
    super();

    this.stageDataIntoQueue();
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METTransferOrderBackOrderCancelContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Stages data into queue.
/// </summary>
void stageDataIntoQueue()
{
    #OCCRetryCount

    contract = dataContract as METTransferOrderBackOrderCancelContract;
    topPickingProcessId = newGuid();

    try
    {
        ttsbegin;

        METTransferOrderBackOrderCancelQueue::cleanUpQueue();
        this.stageTransferLines();

        ttscommit;

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        // catch the errors so processing can continue
        curext(); // avoids a warning about an empty block
    }
}

/// <summary>
/// Stages transfer lines.
/// </summary>
void stageTransferLines()
{
    METTransferOrderBackOrderCancelQueue queue;
    METInventTransferTableExt metTransferTable;
    InventTransferLine transferLine;
    InventTransferTable transferTable;
    int daysFromShipDate;
    date today;

    today = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    daysFromShipDate = real2int(contract.parmDaysFromShipDate());

    insert_recordset queue(ProcessId, InventTransId)
        select topPickingProcessId, InventTransId from transferLine
                where transferLine.RemainStatus == InventTransferRemainStatus::Shipping
                &&    transferTable.ShipDate + daysFromShipDate <= today
            exists join transferTable
                where transferTable.TransferId == transferLine.TransferId
                &&    transferTable.TransferStatus == InventTransferStatus::Created
            exists join metTransferTable
                where metTransferTable.InventTransferTable == transferTable.RecId
                &&    metTransferTable.AllowBackorder == NoYes::Yes
                &&    metTransferTable.TransferType == METCrossDockTransferType::None;

}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    contract = _taskDataContract as METTransferOrderBackOrderCancelContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METTransferOrderBackOrderCancelContract();
}
